WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (201::BIGINT, 'Sus clases son entretenidas, su forma de explicar si es diferenten no es metodico, realiza y deja practicas más dificiles que los examenes pero ayuda bastante, punto negativo es que si califica los examenes y tareas muy tarde'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'ffee319b9592f029431b30834bd8d6ec00b27fcb903c3ce59360c5fd7adc6760'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Hay q estudiar antes de la clase para entender de q esta hablando, pero es buen profe y buena gente. Hace las tareas interesantes y pocos quices'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '608e612e847d5679feae1f75beeb3802b65fe8af55b0ddaff93efcab7c548179'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'La verdad no se le entiende casi nada, hace pocos ejercicios de práctica y los que hace casi no se le entienden, se nota que lee las diapositivas, como persona es bueno, pero como profesor es fatal, prepárate para ser autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'a60972593d8906c3a7b20968e1a604e12aefe411d3323eef6cde2466cb895c4d'::TEXT, ARRAY[922]::BIGINT[]),
    (201::BIGINT, 'Hay que ponerle atención para entender bien y practicar luego un poco pero solo con eso ya se logra pasar bien los exámenes y califica relativamente suave, no hace quices solo tareas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'eafd57c7051228f7866ac2cce4d85ab562ab71b2419e6231555f2e3d1fd2223d'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Vomitivo. Explica "decente" pero usted va a tener que ser mayormente autodidacta. No revisa nada hasta que le toque subir actas. Pero las tareas que el deja no las revisa y solo pone el 100'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, '738386db73ee4f9db49bbc01a0cc26a4192f2fe977ccdb5b3f472abd1c226023'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es buena gente y califica suave, pero hay que ser bastante autodidacta. Parece que no revisa los trabajos y al final solo pone 100. Sí hizo más ejercicios de examen cuando se lo pedimos, pero las clases siguen siendo confusas. Sube notas hasta el final, entonces uno no sabe cómo va para repo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '58309b50011b825feec8555f82c8241e7bc8e95bbb926e533324d192a1244ae8'::TEXT, ARRAY[922]::BIGINT[]),
    (201::BIGINT, 'Las clases son confusas, los ejercicios son tipo examen, pero no los resuelve nada claro. Empezando por que todo el ejercicio lo resuelve en tres pasos, no resuelve las integrales ni nada. Eso hace que entender los ejercicios sea muy difícil. Es vago, dura un montón revisando evaluaciones. Norecomie'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '83b1d0264fad0e9ec2b77a75114b97696921bad9632e24fec9f19ea239d01ab9'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'El profe no es el peor, pero no se le entiende, no matricularía con él, califica un poco suave, pero no explica los temas demasiado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '4d0dd63b4e04a7318f8cc55ada996b7627ec925f555aa1727beb1e8f9d022c97'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Es muy buen profe, se entiende que la materia es muy complicada y por eso da la clase siendo un poco más explicativo y ejemplificador, valora demasiado la participación y ayuda bastante si usted le pide ayuda, es un toque arisco y odioso, pero usted céntrese en aprender y listo, pasa sobrado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, '85c3338fa50a62720648f203874d0caa667601958fef5d7ada46a30b38edd0f8'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Explica raro pero es buen profe en general. Hay que ser autodidacta y deja trabajos en grupo. Tarda en entregar las evaluaciones y ayuda si usted le pone y participa en clase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, '11f28ea4cb07c24b5d37ef487b9249e5e4acbfde8c9c58b52f83917a725e984e'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'A pesar de que uno se esfuerce cuesta mucho entender y sacar las mejores notas, si tiene opción de matricular con otro profe hágalo, pues con este va a sufrir hasta el último momento. Debería tener una nota más baja pues realmente el curso se complica mucho con este profesor.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2026-02-06T00:00:00+00:00'::TIMESTAMPTZ, '63f704ea7f520dceb93ecbbc52d3dc24cad49561bf6ef6ff7053f96d6db6a3da'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'En general, es buen profe. Tarda mucho en entregar resultados, no se da cuenta si va a repo hasta 3 días antes, las clases son un poco aburridas pero cuando falta poco para exámenes, se dedica solo a hacer ejercicios. No hace quizzes,si es autodidacta o lo lleva por segunda vez, es muy buena opción.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'cd0a66b58140be627cf221f01111a6214c91ffa768adc90b10ed0154feae97a9'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'La vdd no me logré acoplar a sus explicaciones, no siento que sus clases fueran tan buenas, si acaso es bastante abierto a consultas y tiene mucha paciencia, sus presentaciones son recortes del libro y ya, no hay soluciones del ningún ejercicio y eso hace mucha falta para estudiar, califica algo sua'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ffbaf57746f61f9fcc877e8659eefaf44fc3f90db151aca664dc170558362640'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'El curso como tal ya es duro, pero él comparado a otros profes es el "GOAT". Increíblemente si explica bastante bien la materia, por lo menos para entender. A veces es algo arisco para hablar, pero no te tomes nada personal ya que si valora mucho la participación.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1a3991c321862014116e6b90414a9ed843cde7dfc80f3b0f92b2d252f8895efa'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'El profe explica bien, es claro, responde amablemente cuando uno realiza preguntas, valora mucho la participación en clase. El curso es difícil como tal, pero el profe hace que sea un poco más sencillo de entenderlo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5799ad11a9e6f6eba155a71c9d92f3322a63efdf5d31b46a19895b472c952bcd'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Califica muy duro, igual que Pineda. La diferencia es que no sabe explicarse bien a la hora de dar clases, se enreda demasiado y hace que uno encuentre en qué parte del ejercicio falló, a veces no explica todo, solo dice lo que hay que hacer. No da teoría. Si uno no participa le pregunta mucho'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '07d2093c496d0d5a8f25cc810cdb28ba63697734411e1a99350619b4cb2982c7'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Si usted no es autodidacta ni lo intente, es demasiado confuso, no da teoria y tras de todo califica durisimo. Matricular con el es quedaada asegurada'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-05-12T00:00:00+00:00'::TIMESTAMPTZ, '87be803a4e27614ad8055d1236197bcc35f64c41e2bc3d0b533b68d88c786576'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Clases desordenadas y confusas, no lleva un material ordenado ni la clase lleva un cronología, por lo que es fácil perderse'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-07T00:00:00+00:00'::TIMESTAMPTZ, '54244f5e3f7519c230fe787515376106885fd64cf2417a75f07a1b42c4619ce1'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'En general es bueno, la asistencia no es obligatoria, y comparte clases de semestres pasados'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '6ba783407b8a9b800b11e4e41a2e2d2dbfcb17e14af2c80b979a94793f5f159a'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es bueno resolviendo dudas y calificando, pero sus clases se hacen tediosas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-01-25T00:00:00+00:00'::TIMESTAMPTZ, '30529cd065981c2f35ebe1405c29b4d63851be4fdae858914fcdf019e4d06184'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'La verdad ni si quiera sé cuándo se vio que tema, no explica teoría, se centra en ejercicios, dura todo el semestre en calificar. Me agradó que si uno tiene una duda no tiene problema con explicar las cosas hasta 4 veces.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2024-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'c7bbe2bce70cd009f5955580eab0b05ff5823d9d1eda74d94c79a33b2fa60ddb'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'A pesar de que solo me impartió 1 clase, calificó el último examen y proyecto,me pareció muy bueno y centrado en lo que es el curso, sin desviarse tanto del tema…a tal punto que casi todos los compañeros quedamos fascinados con sus métodos. Quizá se debió a que el profe que teníamos era una pega.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'b5d5d14d96b2eee071da5da1e444fc0b4469adfef777c29aefc68582bfb87d5c'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Para lab de fisica esta bien, es un curso sencillo pero si hay que estar haciendo los informes que son bien pesados. Cumple bien lo unico es que duro todo el semestre en dar las notas de los trabajos entonces lo agarra a uno por sorpresa.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '9126e0b927cb28aa644a4b40e6907a6b1763af29a513eed6ef74aeb34271aab0'::TEXT, ARRAY[607]::BIGINT[]),
    (201::BIGINT, 'Si pueden meter con otro profe sería lo mejor, realmente se salta mucha teoría qué si es necesaria para entender mejor el curso, se enfoca en resolver ejercicios pero al no tener bases claras no ayuda en mucho, si es una persona autodicta puede ser que le funcione.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-07-30T00:00:00+00:00'::TIMESTAMPTZ, '25da22ac55c990290f46c9ea7505f4028d44785062284108b590282fc060be9b'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Para mi es el mejor profe de física 1, es cierto q no es un profe para todos, ya q la teoría la ve rápido y se centra en ejercicios de examen pero eso ayuda mucho, el 10% q evalúan los profes hace mini proyectos pesados q casi siempre evalúa 0 o 100 depende si entrego o no, uno sale en semana 13/14'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'fc102c12db88dc076b6a3cd4332cb8f85f5d90c26452260be6f9c00548ae16d2'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Curso complicado, pero el profe es bastante buena gente y ayuda mucho'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '136559d8a1bf84b126aa3d31ef2347c2a5a5fde3ee0237f6f8006edc0b7fc207'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Explica solo ejercicios y la teoría por encima. Las clases se hacen largas. Pasa lista, y solo le afecta la falta de asistencia si no pasa el curso. Es buena gente sin embargo no lo recomiendo ya que basicamente hay que ser autodidacta. Revisa todo como un día antes de la repo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '023960495bf21b27029f5c82f6357919abffe94d882a6c19e260c7663817878e'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'no da mucha teoria, se centra en hacer ejercicios y examenes pasados. las clases son aburridas. es muy chill, califica todo faltando poco para la entrega de actas. es buena nota con las dudas, y tiempo de las tareas. hay que ser autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7c9cdc85bfcf186986cf2c10537133f6b1568dab1f96917fc79ded18c367e301'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Esta bien...'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, '7ae7ffc4f33721da021b393ceec472ba78e39b8262e24d8790efb520cc793dff'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es buena persona, pero sus clases son muy aburridas. No explica la teoría y pone ejercicios difíciles en clase. Nunca supe si la asistencia era obligatoria ya que pasaba la hoja de asistencia pero en las calificaciones nunca se vio reflejado. Lo recomiendo si van a llevar el curso de nuevo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2024-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'c1db87ba638e032a53b2118043aa48da9c507f70e162fbaa271608d112b3b4b9'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El profesor ayuda si uno le pide ayuda. Cualquier duda la resuelve en clase, y si le interesa que uno aprenda. Sin embargo, sus clases son largas, y uno se puede quedar dormido, es fácil perderse si uno no tiene un algebra decente. No ve NADA de teoría. Se concentra en ejercicios de examen.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '9cfb5c84186ea1816be699474d98545c90826b70bf754606d250d76ad069563a'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'A mi me parecio buen profe, sin embargo sus clases son muy aburridos y pierde muy facil al estudiante, ademas no explica mucha teoría se centra en práctica, si a usted le cuesta concentrarse busque un profesor mas activo por que con el se duerme. Personalmente no lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f509291ee34b634982176f046897e581ad0f524c1e66e0ddca63401e0c3aaa24'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es un buen profe, pero casi nunca explica teoría, en todas las clases lo que hace es resolver ejercicios.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2023-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'aa743341204b85ce614e11244d573875c66f3067cf4b570070424e42e8d9edb6'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Explica muchos ejercicios prácticos de alto nivel. No se preocupa mucho por la teoría, va más a la parte práctica. No hace quizzes, solo proyectos grupales muy sencillos. Califica muy suave, en consulta explica hasta las tareas. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7e7a76eeace76f2af2fdd3643bdbbae8e4981035c6f79289ee69d9ee69555ec3'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Las clases de él son un toque confusas, siempre escoge los ejercicios mas difíciles para las tareas, dura DEMASIADO en entregar notas. El va super chill en las clases que se aburre uno y cuando resuelve ejercicios a veces no se entiende lo que hace'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5ba980122153131211e01252d2bae4edda5b5d0a7660803f94a75ce0f691fd49'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Las explicaciones son muy rápidas y no entra en detalles con las ecuaciones, el material brindado es desodernado y dura mucho en calificar. Una actitud muy relax que solo da sueño en las clases.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '160c68e365c74782bf3fea375b2fdfd504923a35cc4d92440ea849452988be4c'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '416c56ba2ee2ff233009fea7fe0528829e663d6fe123e6c00aa17c406e974dee'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es muy bueno dando el curso, es muy rápido para explicar y a veces se salta pasos en ecuaciones, pero hace muchos ejercicios de práctica. Ayuda mucho al estudiante con la tareas, y no hace quices deja mínimo proyectos muy fáciles y si ve que usted puso de su parte al final le ayuda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '56a95c070617ccaa3a55885c19ad7dbef0efd82c48b6cb27f1dd2f0916d44b66'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Las clases se hacen confusas por su manera de explicar la materia, escoge los ejercicios mas difíciles para las tareas, dura demasiado en entregar notas, es un frescaso el mae, para alguien que esta repitiendo física no veo el problema de matricular con el, de lo contario no lo haga'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Deja trabajos largos']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd3c89b58d09469c6f511dc6ade320c60f5eef5e40cff564bdfec7550dc6759a8'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Explica confuso, es dificil seguir el hilo de la explicación y el material de apoyo está muy desordenado , tarda mucho en calificar trabajos, pero cae bien, es tranquilo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f53d35c0a6b6d2e5277510f7e849b5f99ebd1564404f81f28e07ebac1062baef'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'No explica excelente, puede ser confuso, pero se entiende. El profe es demasiado fresco entonces no le importa mucho nada... Las tareas fueron complejas pero se logran. No la primera opción para matricular'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1e1c1091b2cc7e884b817b32ee6fb6589ef43bd46831d8c1b5e5a24dc6b1db84'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Explica muy bien, se disfruta la clase. Es duro para calificar examens, pero se pasa el curso solo entregando trabajos, para los cuales es muy flexible para calificar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, '60f9e273c72b0d23a1eb826b636af43428bf2aef558fe87cf9c59662c2777c6f'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El profe ayuda bastante y es muy accesible con dudas y entregas de trabajos, lo único malo es que dura mucho para entregar las calificaciones de los mismos, pero se compensa por el hecho de que si usted le pide más tiempo para entregar un trabajo el accede.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '4b77e9e609dc8a1893f046873398f10d5b574031ba626564a283f0a11ff22505'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El profe es amable y paciente para explicar. Si uno tiene consultas siempre tiene muy buena disponibilidad para ayudarlo a uno. Y se preocupa mucho porque uno entienda la clase'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bbb35953cc0c24782c41f6c12fdb086a2d30682d54bb0fe10f2268d42fd259ed'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es Física II, se tienen que ver todos los videos del gran Cesar Antonio Izquierdo Merlo para entender la materia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '8bc5fc8db75aa42c2ceaeb2e345777c7b7f4cf42a3503a13306c01a9edfbf3fc'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'El curso en sí es bastante pesado, pero el profe trata de ayudar siempre que se le pide. A veces dura mucho en entregas calificaciones.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, '9d68b3a08dc4805261e96a0360456311502c8fb2754bcb6de3a401e7daa7038f'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-29T00:00:00+00:00'::TIMESTAMPTZ, '8cd8917da5e2eb4dd05150b0002a3b20ce188d8cccd9df431cf6c8d67f5ce1a4'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Gente, no se preocupen con cual profe matricular física 2, que ninguno sirve y al final se tiene que pasar el curso con los videos del Licenciado Izquierdo. Las evaluaciones son rudísimas comparado a lo visto en clase y este mae no califica nada, semana 14 y de 10 eval. ha calificado 3, un dolor.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-10-29T00:00:00+00:00'::TIMESTAMPTZ, '2e67d66fdc8faf8cdf4bde601676a4fc23111171e0a13066f1599c65cdcb5e81'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Lleve el curso con el virtual, lo recomiendo. La cátedra de física al no hacer exámenes permite que el curso sea fácil de llevar de manera asincrónica y el profe es perfecto para eso, muy flexible con las evaluaciones. De vez en cuando veía las grabaciones conforme las ocupaba para trabajos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-08-06T00:00:00+00:00'::TIMESTAMPTZ, '4d7a2a8d63ada09a6b64a538d5d60c52a7c264fb5497c693d45319dc5e0579e2'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'él es muy paciente para explicar la veces que sea necesario, es muy muy suave para calificar, las clases son un poco largar porque él no avanza hasta asegurarse que todo se está entendiendo. Lo mejor sería ver la materia antes de las clases, pero eso pasa en casi todas las mates y las físicas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'bebdf96d6c135a2419b530fd19dc70703e2fc0fbd6ae7a455cde1d3644bca72e'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El profe como tal es tuanis pero no explica casi nada, las clases son solo para resolver ejercicios y pocas veces repasa teoría. Si se le facilita estudiar solo, lo recomiendo. Califica suave. (Virtual)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f2bf0371acb0211ef68e8467f45cadf6c992e9194abfa9fb51d7141e69cbe196'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'La verdad en modalidad virtual, entré a clases con él. El material que subió la cátedra estaba bastante claro, pero si surguian dudas podía preguntarle sin miedo. Explica hasta que usted entienda y da retroalimentación. En clases presenciales suele ir bastante rápido y es muy confuso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '0895a75544a26723ed435d5e4283845245b3d693c76de7eaba089da4fe6355cf'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'No explica bien y es súper lento para dar las clases, no explica lo necesario para los exámenes. Se pierde mucho en clase'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '8f678c00cfd3e1b365045c6e4511a8308008a0f2f660541136c07e074f0eef16'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'es muy relax con todos los trabajos, se debe estudiar bastante por aparte.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'cc30b7c99f9c3514ab3987845d8a1cbef1f9259421b3f29eb2672dcc02161d8c'::TEXT, ARRAY[607]::BIGINT[]),
    (201::BIGINT, 'Muy buena gente , es muy flexible, a veces cuesta entenderlo pero si uno le pone él le ayuda y es muy relax con las tareas , sin embargo hay que hacer mucha practica y estudiar por aparte. (el libro ayuda )'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-11T00:00:00+00:00'::TIMESTAMPTZ, '1d278304501538b6d8b731cb497f5bf4a7dd888673e6a56564ea683fff6572c6'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El curso por sí solo, es duro. Este mae promete en el sentido de que hace ejercicios muyyy pesados en análisis, de nivel de examen o incluso más. Lo único "malo" es que hay que llegar con toda la materia estudiada del libro para entender qué carajos está haciendo. Él es muy buena gente e interesante'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1c30ff785d0a94a486a7cc8fc9ac832163f74386865415db2ee78a524210485b'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'El profesor no es bueno explicando y cuesta entenderlo, pero si ayuda bastante si nota interés.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'afb87a71cf1b3ba20099a1c3841a027e9ba37fcf57e5d6f0f2b407e12c490809'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es muy buena gente, si uno va a todas las clases y hace preguntas se aprende. Tareas muy largas pero se pueden hacer en parejas. Califica mucho el procedimiento y da puntos si uno no estaba tan perdido. Si va a todas las clases y estudia con Cesar Izquierdo se pasa muy fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '489a729c16d7fa3bf0af1300ee6dbdc08e9aa7d28d45ffc27b21462299e72e86'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El mae en general es buen profe, sin embargo, se debe prestar bastante atención para entender pues no explica de la mejor manera. A veces explica cosas innecesarias. Deja tareas largas pero son bastante útiles.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b4e142f42e0246959b32669bc93d69dce086efb76b60fde8116aa13706775627'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es buena nota, le gusta que el estudiante entienda. Sólo que da la clase un poco aburrida y es muy teórico, explica lento y hace pocos ejercicios. Califica justo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '14107b37c71fab6634b05c0dffbc4f22ce07f02154fc908108086fe0172920ea'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'La clase es sumamente aburrida, pero aparte de eso no hay mucha queja. Da la materia muy teórica y explica todas las veces que sea necesario. Tiene mucha paciencia y califica justo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'da6912e58ef0f48d8096ca5652e8c7faecd420a2dad6567aae6af070dcdde27a'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Las clases son aburridisimas, son casi completamente teóricas exceptuando unos pocos ejercicios que hace antes de los exámenes, deja tareas y quices en línea, ayuda mucho y califica bastante suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'cadc6f09196fbc0e96ba07f4a7b7f84f75d4b49806e269a42ee3336d9099bdba'::TEXT, ARRAY[922]::BIGINT[]),
    (201::BIGINT, 'Es muy paciente en consulta, se sale del esquema tradicional de enseñanza logrando clases más dinámicas y entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd1c4a0d8c9abdf0e37e221fd17020ae0511ec15385a6d7793649cac44d3406a7'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'realmente es muy bueno para explicar, hace pocos ejemplos pero son los necesarios para entender lo unico malo son las tareas largas (aprox 50 ejercicios) y es una buena persona'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '86b31cc41bbe1ae71979630e635982ea2b731aff101362292b2d24ac825d83d5'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Un buen sujeto, a veces estaba mamando con la materia y los ejercicios no le salían, pero el mae ve el esfuerzo y se interesa por los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '80b48945c0f782386186269ea17d4532bee58e70eebce38017ec6b7f129b2c0a'::TEXT, ARRAY[922]::BIGINT[]),
    (201::BIGINT, 'No es un mal profe, realiza pocos ejercicios pero los que hace son útiles En ocasiones las clases se tornan aburridas, pero sí se pasa'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7b2659a200d4a7aa37a9811a04e5fc27989e6eb34e31e7753637903edd76c3d3'::TEXT, ARRAY[922]::BIGINT[]),
    (201::BIGINT, 'Muy mal profesor, enserio. Este semestre se hacía mucho desorden y explicaba cosas de "cultura general" que le quitaba toda la clase, cuando explicaba duraba una clase haciendo solo UN ejemplo. Tareas LARGAS que no da mucho chance, dura para entregar examenes, no hace quices y pasa lista.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'fd6af8103e008cda73de2c484133754c5c954e856eb4a67741052d6562489a4e'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'explica super bien, con ejemplos claros el mejor profe de fisica es una CRACK'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'e3059f3f9996fdb7e634cefc4615c0d861495e316d79b7aa1bd3cc87ab6d9450'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Se nota que le gusta lo que hace y le interesa que el estudiante aprenda, pero su metodología y su forma de explicar no es para nada buena. No es el peor profe, pero bo lo recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'f403773fa70fdebc6234899be2b01b12cca083fabad9fd7c2e82cc1875ce3dac'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Se nota que le gusta la materia que da, el método no es el mejor pero se le entiende si pone atención y toma apuntes. Es una exelente persona y está siempre dispuesto a ayudarle a uno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'da62d28c504a94e08a5f66f5a763bf2d26fbfcfa89b9bf37c9a7306ae5c9939f'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'A veces cuesta entenderle bien lo que esta haciendo o explicando, siempre intenta que el estudiante aprenda, deja tareas aparte de las de Cátedra que sirven como practica para cada examen. Si esta repitiendo el curso, super recomendado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, '8d22674379a02ee5558dd18f1020745ec5df94ece472457971e285c8d783a7f0'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Terrible método de enseñanza, pésimo manejo del tiempo y por ende muy pocas evaluaciones que terminaban perjudicando el aprendizaje estudiantil. En adición a esto, no me dijo que tenía derecho a reposición debido a que subió las notas finales dos días antes del examen. No lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-12-04T00:00:00+00:00'::TIMESTAMPTZ, '9ed3c52d5fcbfaec627235ea09d59312a864ec7b224f0525f751819a5ba2992d'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Un profe muy relax con las entregas de los informes. Tiende a explicar regular, ni bien ni mal. Aveces se espera a que todos hagan las cosas mal para corregir a la clase. Por esto mismo nunca da tiempo de hacer el informe en clase solo el experimento. No le importan las llegadas tardías.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'fe10dff2437002cb1a2efe32c7ead45581aa32feda011a1bb300fb32eac381c9'::TEXT, ARRAY[607]::BIGINT[]),
    (201::BIGINT, 'Explica muy bien, atiende a las dudas y califica normal, el truco para pasar con él es poner mucha atención y participar en clases!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-10-28T00:00:00+00:00'::TIMESTAMPTZ, '410a0aab423440008bcf26f1cf83057dd69b8583666a34e27d1af1ae46bbeda0'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Pierde mucho el tiempo y no explica muy claro. Tarde demasiado en calificar. La ventaja es que no hace quices, sólo deja la tarea de la cátedra.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'e1aed1736fd6e15c4d95f898e7494e253cc73b7edbc9a363c6779af9c403b29c'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Gasta mucho tiempo en cosas innecesarias. Las tareas las deja una encima de otra y no le interesa. Sus clases son muy aburridas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7a430298a860e94f0844b3633bf9488cac0a773326f298e7ccfaf335b4810edb'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'El mae como persona es excelente, como profesor es bueno también, pero suele brincarse muchos pasos a la hora de realizar ejercicios. Él ayuda dejando buenas tareas, y no califica duro, además se interesa de forma general por el estudiante; es una persona muy amable. *Vean también a Cesar Izquierdo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'caeef18767c7a226dc279e42ba557166961a84ff5edbfd1c79c806e0e5b9f6dc'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'No es para personas que lleven el curso por primera vez, bastante desordenado e irresponsable, prepárese para esperar la calificación de los exámenes por lo menos tres semanas después de hacerlos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1f54ac39da5a20ffd1dd6421a1d0542a791c3c4b4478dfe2776e7537aed2b3e1'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Buen profesor no califica tan duro y se preocupa por que los estudiantes aprendan'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '35157665568614400fbdcaa47a39c67a45b8036753320df3f8330d74fbea3453'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Es profesor es un toque desordenado, así que si le gusta el orden matricule con otro profe, en general es un profe promedio, no es dura calificando exámenes y trata bien a los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e0c04239032c8b7a87178aadc7ce46d2c6b4fb258f4627d1faa43d8bd985c77d'::TEXT, ARRAY[630]::BIGINT[]),
    (201::BIGINT, 'Es sumamente irresponsable, es un inútil y siempre pone excusas porque le da pereza revisar exámenes, también es irrespetuoso y cochino'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '9ec2a530fcd69d86049e69f230680bfaa1c3a176ce8905287302d05420b01f8c'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Si le pides ayuda o le dices que no entiendes, te dice “piense un poquito” a pesar de que llevas media clase pensando, se complica demasiado con los ejercicios que pone y explica súper confuso'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-29T00:00:00+00:00'::TIMESTAMPTZ, '8bb5bee546978a99402a179e987e6274db1a0a09687406239a1115f51da93042'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'En las clases se hacen ejercicios más difíciles que en los exámenes y le encanta inventar ejercicios en clase lo que la hace entretenida. Tares cortas y no siempre son de la cátedra por lo que son más difíciles. No entrega las cosas a tiempo, no espere estudiar con su tarea para el examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e0bd3f970fc5172d2315e3a70460fdda07491a01237b4aaf6b32958b239fc178'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Excelente profesor, se preocupa por que los estudiantes realmente entiendan los conceptos de física.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e32a414fbf39d9d548cf2835fa063882c5a95ef0a4950c1225c895d800df80d4'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'bfbd3c576a2370db6c423d993efbae4d604ab75eeddb4453d97d1bbacccc24a0'::TEXT, ARRAY[1369]::BIGINT[]),
    (201::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2017-02-18T00:00:00+00:00'::TIMESTAMPTZ, '5789703f0166623d6142aefb86ae44d3ae9b0275d3fc154a2c2611ba7246d78f'::TEXT, ARRAY[604]::BIGINT[]),
    (201::BIGINT, 'Hace muchas practicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '516675ca3f0545c013a08bffb6fbe803aca7ccbedc201db20f6ba345d8052a41'::TEXT, ARRAY[922, 630, 604]::BIGINT[]),
    (201::BIGINT, 'Califica rudo el trabajo final, hace quices muy difíciles algunos en grupo pero ni en grupo resulta fácil, si le preguntas algo en clase o en consulta no te va a explicar primero tienes que pensar mucho y el te va aclarando pero casi nada.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '7ef5767bd9d7d995b4ba3df2ac3e99c25d7633719406ae3b75c7eaf4f3936525'::TEXT, ARRAY[607]::BIGINT[]),
    (201::BIGINT, 'Tal vez no sea el mejor pero es muy bueno explicando, ayuda mucho, califica suave y lo más importante es un profe tuanis, de los más malos creo que es la mejor opción, aunque lo recomiendo para gente que está repitiendo el curso ya que a él le gusta que los estudiantes piensen un poco por si mismos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'f50585c529a81b306218c538e01f02a456c91afaa449e788dde5ea2cb9009d2e'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
